/* ------------------------------------------------------------
   لوحة الرحلة: المتجر (يمين) → المنتصف → منزل العميل (يسار)،
   طريق منقط بأنيميشن بسيط، وسائق يتحرك حسب progressStage وحده.
   العقد الثلاث مجسمات 3D فاخرة (موديلات ذهبية فوق أرضية 2D) + لافتة
   صغيرة تحت كل أيقونة (المتجر/في الطريق/منزل العميل/السائق)؛ نفس
   المواضع والأحجام والمراسي وأصناف الاختبارات كما هي.
   ------------------------------------------------------------ */
var JOURNEY_NODES = [
  { key: "store", x: 86.7, y: 25, at: 1, icon: "store" },
  { key: "mid", x: 50, y: 65, at: 2, icon: "pin" },
  { key: "home", x: 13.3, y: 30, at: 4, icon: "home" }
];
/* إحداثيات SVG الموافقة (viewBox 0 0 120 40) — نفس الترتيب في LTR وRTL. */
var JOURNEY_D = "M 104 10 C 86 12, 74 24, 60 26 C 46 28, 28 24, 16 12";
/* OP14: مجسمات 3D فاخرة (موديلات ذهبية فوق أرضية 2D) + لافتة تحت كل أيقونة.
   ملاحظة الإنتاج: هذه روابط مؤقتة مولّدة للمعاينة — استبدلها بأصولك الشفافة
   (PNG شفاف ≥256px) متى جهزت، بنفس المفاتيح، دون أي تغيير آخر. */
var MODEL_IMGS = {
  store: "https://user.uploads.dev/file/01db2a1cfc044a65d429449b925d6678.jpg",
  mid: "https://user.uploads.dev/file/b1c45e404d88136e639735cf9b57619e.jpg",
  home: "https://user.uploads.dev/file/381351af084d66dfd4a09445491c0870.jpg",
  truck: "https://user.uploads.dev/file/8b1e0c5cc738b2fe036c15f05fc14908.jpg"
};
var NODE_LABELS = {
  store: { ar: "المتجر", en: "Store" },
  mid: { ar: "في الطريق", en: "On the way" },
  home: { ar: "منزل العميل", en: "Customer home" }
};
var MOVER_LABEL = { ar: "السائق", en: "Driver" };
/* OP15: هندسة الطريق ككسور (0-1) لرسم الخلفية الحية على نفس المسار. */
var ROUTE_SEG1 = [{ x: 0.8667, y: 0.25 }, { x: 0.7167, y: 0.30 }, { x: 0.6167, y: 0.60 }, { x: 0.5, y: 0.65 }];
var ROUTE_SEG2 = [{ x: 0.5, y: 0.65 }, { x: 0.3833, y: 0.70 }, { x: 0.2333, y: 0.60 }, { x: 0.1333, y: 0.30 }];
function routeBezier(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y
  };
}
function routePoint(s) {
  s = Math.max(0, Math.min(1, s));
  return s < 0.5
    ? routeBezier(ROUTE_SEG1[0], ROUTE_SEG1[1], ROUTE_SEG1[2], ROUTE_SEG1[3], s * 2)
    : routeBezier(ROUTE_SEG2[0], ROUTE_SEG2[1], ROUTE_SEG2[2], ROUTE_SEG2[3], (s - 0.5) * 2);
}
var JOURNEY_FRAC = {};
JOURNEY_NODES.forEach(function (n) { JOURNEY_FRAC[n.key] = { x: n.x / 100, y: n.y / 100 }; });

function lerpPt(a, b, k) { return { x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k }; }

/* ------------------------------------------------------------
   اللوحة: طريق + عقد + سائق حسب progressStage.
   ------------------------------------------------------------ */
/* ------------------------------------------------------------
   OP15: خلفية حيّة صادقة — نبض العقدة الحالية + تدفق الطريق +
   توهج السائق. مرتبطة بالمرحلة فقط (بلا GPS)، وتتوقف مع إخفاء
   الصفحة/تقليل الحركة، وتُنظَّف عند unmount.
   ------------------------------------------------------------ */
function TrackBg(props) {
  const canvasRef = useRef(null);
  const ship = props.ship || {};
  const reduced = !!props.reducedMotion;
  const stage = (ship.progressStage == null ? null : Number(ship.progressStage));
  const live = stage != null && !ship.exceptional;
  const cl = stage == null ? 0 : Math.max(0, Math.min(4, stage));
  const pct = cl / 4;
  const posS = (typeof props.posS === "number" && isFinite(props.posS)) ? props.posS : pct;
  const curKey = !live ? "" : (cl >= 4 ? "home" : (cl >= 2 ? "mid" : "store"));

  useEffect(function () {
    const cv = canvasRef.current;
    if (!cv) return undefined;
    const wrap = cv.parentElement;
    const ctx = cv.getContext("2d");
    let raf = 0; let w = 0; let h = 0; let dpr = 1;
    function fit() {
      const r = wrap.getBoundingClientRect();
      dpr = Math.min(1.5, window.devicePixelRatio || 1);
      w = Math.max(2, r.width); h = Math.max(2, r.height);
      cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    }
    function draw(t) {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const u = Math.min(w, h) / 200;
      let i; let p;
      for (i = 0; i < 30; i++) {
        const s = (((i / 30) + (reduced ? 0 : t / 46)) % 1 + 1) % 1;
        p = routePoint(s);
        const doneS = live && s <= pct;
        ctx.fillStyle = doneS ? "rgba(217,183,119,.5)" : "rgba(176,58,46,.42)";
        ctx.beginPath(); ctx.arc(p.x * w, p.y * h, (doneS ? 2 : 1.6) * u + 0.6, 0, 6.283); ctx.fill();
      }
      if (live && curKey && JOURNEY_FRAC[curKey]) {
        const nf = JOURNEY_FRAC[curKey]; const nx = nf.x * w; const ny = nf.y * h;
        for (i = 0; i < 3; i++) {
          const tt = (((reduced ? 0 : t / 1.7) + i / 3) % 1 + 1) % 1;
          ctx.strokeStyle = "rgba(217,183,119," + ((1 - tt) * 0.34).toFixed(3) + ")";
          ctx.lineWidth = 1.6;
          ctx.beginPath(); ctx.arc(nx, ny, (10 + tt * 52) * (w / 600) + 8, 0, 6.283); ctx.stroke();
        }
        const m = posS <= 0.5
          ? lerpPt(JOURNEY_NODES[0], JOURNEY_NODES[1], posS * 2)
          : lerpPt(JOURNEY_NODES[1], JOURNEY_NODES[2], (posS - 0.5) * 2);
        const mx = (m.x / 100) * w; const my = (m.y / 100) * h; const R = 30 * (w / 600) + 10;
        const g = ctx.createRadialGradient(mx, my, 2, mx, my, R);
        g.addColorStop(0, "rgba(217,183,119,.30)"); g.addColorStop(1, "rgba(217,183,119,0)");
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(mx, my, R, 0, 6.283); ctx.fill();
      }
    }
    function onResize() { fit(); if (reduced) draw(0); }
    fit();
    if (reduced) draw(0);
    function loop() {
      if (typeof document === "undefined" || !document.hidden) draw(performance.now() / 1000);
      raf = requestAnimationFrame(loop);
    }
    window.addEventListener("resize", onResize);
    if (!reduced) raf = requestAnimationFrame(loop);
    return function () {
      try { cancelAnimationFrame(raf); } catch (e) {}
      try { window.removeEventListener("resize", onResize); } catch (e2) {}
    };
  }, [live, cl, pct, posS, curKey, reduced]);
  return <canvas ref={canvasRef} className="tk-bgfx" aria-hidden="true" />;
}

function TrackPath(props) {
  const ship = props.ship || {};
  const language = props.language;
  const en = language === "en";
  const stage = (ship.progressStage == null ? null : Number(ship.progressStage));
  const cl = stage == null ? 0 : Math.max(0, Math.min(4, stage));
  const pct = cl / 4;
  const reduced = !!props.reducedMotion;
  const live = stage != null && !ship.exceptional;
  /* موضع السائق: store→mid ثم mid→home (استيفاء خطي بسيط). */
  /* OP15: بصمة الأيقونة — إزاحة أمامية شكلية عند الصفر لتفادي انطباق
     السائق على عقدة المتجر؛ التقدم الذهبي يبقى على pct الحقيقي. */
  var posS = pct <= 0 ? 0.10 : pct;
  var rp;
  if (posS <= 0.5) {
    rp = lerpPt(JOURNEY_NODES[0], JOURNEY_NODES[1], posS * 2);
  } else {
    rp = lerpPt(JOURNEY_NODES[1], JOURNEY_NODES[2], (posS - 0.5) * 2);
  }
  const curKey = !live ? "" : (cl >= 4 ? "home" : (cl >= 2 ? "mid" : "store"));
  const ariaSummary = en
    ? "Shipment stage " + (stage == null ? "unknown" : stage) + " of 4"
    : "مرحلة الشحنة " + (stage == null ? "غير معروفة" : stage) + " من 4";
  return (
    <div className="tk-path-wrap">
      <TrackBg ship={ship} reducedMotion={reduced} posS={posS} />
      <svg
        className="tk-journey"
        viewBox="0 0 120 40"
        role="img"
        aria-label={ariaSummary}
        preserveAspectRatio="none" /* OP16: يتمدد مع اللوحة على الجوال؛ السماكة ثابتة عبر vector-effect */
      >
        <path d={JOURNEY_D} className={"tk-road-base" + (reduced ? " is-static" : "")} pathLength={100} fill="none" />
        {live ? (
          <path
            d={JOURNEY_D}
            className="tk-path-done"
            pathLength={100}
            fill="none"
            strokeDasharray={(pct * 100) + " 100"}
          />
        ) : null}
      </svg>
      {/* العقد الثلاث — مجسمات 3D فاخرة + لافتة (نفس الموضع؛ أصناف الاختبارات محفوظة). */}
      {JOURNEY_NODES.map(function (n) {
        const reached = live && cl >= n.at;
        const lbl = (NODE_LABELS[n.key] && NODE_LABELS[n.key][en ? "en" : "ar"]) || "";
        return (
          <span
            key={n.key}
            className="tk-pin"
            style={{ left: n.x + "%", top: n.y + "%" }}
            aria-hidden="true"
          >
            <span
              className={"tk-node tk-lux tk-st" + (reached ? " is-on" : "") + (curKey === n.key ? " is-cur" : "")}
            >
              <img src={MODEL_IMGS[n.key]} alt="" draggable="false" />
            </span>
            {lbl ? <span className="tk-nlbl">{lbl}</span> : null}
          </span>
        );
      })}
      {/* السائق — مجسّم 3D + لافتة، يتحرك حسب المرحلة فقط. */}
      {live ? (
        <span
          className={"tk-pin is-mv" + (reduced ? " is-static" : "")}
          style={{ left: rp.x + "%", top: rp.y + "%" }}
          aria-hidden="true"
        >
          <span className="tk-mover tk-lux">
            <img src={MODEL_IMGS.truck} alt="" draggable="false" />
          </span>
          <span className="tk-nlbl">{en ? MOVER_LABEL.en : MOVER_LABEL.ar}</span>
        </span>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------
   بطاقة نتيجة واحدة (علنية أو مسجلة
بطاقة نتيجة واحدة (علنية أو مسجلة — نفس العرض، بلا PII).
   ------------------------------------------------------------ */
function TrackResult(props) {
  const ship = props.ship;
  const language = props.language;
  const en = language === "en";
  const dispatch = useAppDispatch();
  const meta = op1GroupMeta(ship.group, language);
  const detail = op1DetailText(ship, language);
  const updated = ship.lastUpdatedAt ? formatContractDay(ship.lastUpdatedAt, language).text : "";
  const [cancelState, setCancelState] = useState("idle");
  const [cancelMsg, setCancelMsg] = useState("");
  const orderId = Number(ship.orderId) || 0;

  function askCancel() {
    setCancelMsg("");
    setCancelState("confirm");
  }
  function sendCancel() {
    if (!orderId || cancelState === "busy") return;
    setCancelState("busy");
    setCancelMsg("");
    const key = getOrCreateCancelIdempotencyKey(orderId, "customer_request");
    requestShipmentCancellation(orderId, { reason: "customer_request", idempotencyKey: key }).then(function (r) {
      setCancelState("done");
      /* ★ R8: رسالة الخادم تُعرض كما هي إن كانت بلغة العميل، وإلا البديل الودود */
      const rawCancel = String((r && r.message) || "");
      setCancelMsg(rawCancel ? (toUserMessage(rawCancel, en ? "en" : "ar") || (en ? "Cancellation request sent" : "تم إرسال طلب الإلغاء")) : (en ? "Cancellation request sent" : "تم إرسال طلب الإلغاء"));
      try { dispatch(uiActions.toastShown(en ? "Cancellation request sent" : "تم إرسال طلب الإلغاء")); } catch (e) {}
    }, function (err) {
      setCancelState("error");
      const c = classifyTrackingError(err, false);
      setCancelMsg(c.message);
    });
  }

  return (
    <div className="tk-result" role="status">
      <p className="tk-line tk-status">
        <b>{meta.label}</b>
        {ship.simulated ? <span className="ck-hint"> ({SHIPPING_SIMULATION_NOTE})</span> : null}
      </p>
      <p className="tk-line">{detail}</p>
      {ship.voucherNo ? (
        <p className="tk-line">
          {en ? "Shipment no.: " : "رقم الشحنة: "}<b dir="ltr">{ship.voucherNo}</b>
        </p>
      ) : null}
      {ship.halfDelivered ? (
        <p className="ck-hint">{en ? "Partial delivery — not fully completed." : "تسليم جزئي — لم يكتمل التسليم بالكامل."}</p>
      ) : null}
      {updated ? (
        <p className="ck-hint">
          {en ? "Last update: " : "آخر تحديث: "}{updated}
          {ship.isStale ? (en ? " (may be outdated)" : " (قد تكون قديمة)") : ""}
        </p>
      ) : null}
      {ship.needsAttention ? (
        <p className="ck-auth-warn" role="alert">{en ? "This shipment needs follow-up." : "هذه الشحنة تحتاج متابعة."}</p>
      ) : null}
      {ship.contractMismatch ? (
        <p className="ck-auth-warn" role="alert">
          {en ? "Shipment status format changed — please refresh the page." : "تغيّرت صيغة حالة الشحنة — حدّث الصفحة وحاول مجدداً."}
        </p>
      ) : null}
      {!ship.group && ship.hasVoucher ? (
        <p className="ck-auth-warn" role="alert">{en ? "Shipment status unavailable" : "تعذّر قراءة حالة الشحنة"}</p>
      ) : null}
      <TrackPath ship={ship} language={language} reducedMotion={props.reducedMotion} />
      {ship.canRequestCancellation && orderId && cancelState !== "done" ? (
        <div className="tk-cancel">
          {cancelState === "confirm" ? (
            <p role="alert">
              <span>{en ? "Send a cancellation request for this shipment?" : "إرسال طلب إلغاء لهذه الشحنة؟"}</span>
              <span className="tk-confirm-btns">
                <button className="oh-btn is-gold" type="button" disabled={cancelState === "busy"} onClick={sendCancel}>
                  {en ? "Confirm" : "تأكيد الإرسال"}
                </button>
                <button className="oh-btn is-quiet" type="button" onClick={function () { setCancelState("idle"); setCancelMsg(""); }}>
                  {en ? "Back" : "تراجع"}
                </button>
              </span>
            </p>
          ) : (
            <button className="oh-btn is-quiet" type="button" disabled={cancelState === "busy"} onClick={askCancel}>
              <span>{cancelState === "busy" ? (en ? "Sending…" : "جارٍ الإرسال…") : (en ? "Request cancellation" : "طلب الإلغاء")}</span>
            </button>
          )}
        </div>
      ) : null}
      {cancelMsg ? (
        <p className={cancelState === "error" ? "ck-auth-warn" : "ck-hint"} role={cancelState === "error" ? "alert" : "status"}>
          {cancelMsg}
        </p>
      ) : null}
      {props.polling ? (
        <p className="ck-hint tk-live">{en ? "Live tracking…" : "نتابع لحظياً…"}</p>
      ) : null}
    </div>
  );
}

