export default function TrackShipmentPage() {
  usePageMeta({ route: "tracking", titleAr: "تتبع شحنتي", titleEn: "Track my shipment" });
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) { return s.ui.language; });
  const en = language === "en";
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });

  const [voucher, setVoucher] = useState("");
  const [query, setQuery] = useState(null); /* {kind:'public',voucher}|{kind:'latest'}|{kind:'order',orderId,invoiceNo} */
  const [ship, setShip] = useState(null);
  const [loadState, setLoadState] = useState("idle"); /* idle|loading|ready|error */
  const [loadError, setLoadError] = useState("");
  const [polling, setPolling] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyState, setHistoryState] = useState("idle");
  const [showPublicSearch, setShowPublicSearch] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);

  const seqRef = useRef(0);
  const abortRef = useRef(null);
  const timerRef = useRef(0);
  const queryRef = useRef(null);
  const customerIdRef = useRef(null);
  const accountRef = useRef(null);
  /* ★ OP4 §F1: مالك دورة السجل المستقل — generation/request token +
     إلغاء الطلب السابق (AbortController؛ fetchServerOrders يدعمه). */
  const historyTokenRef = useRef(0);
  const historyAbortRef = useRef(null);
  const attemptsRef = useRef(0);
  const startedAtRef = useRef(0);
  const resultHeadRef = useRef(null);
  /* ★ الجولة الجديدة §F2: مرآة ref للنتيجة المعروضة — تُقرأ داخل tick
     (closure الـstate قديمة). آخر رسالة حدّ (429) تُعرض عند الإيقاف
     المسبق قبل الإرسال (لا مخرج صامت بلا سبب). */
  const lastRateMsgRef = useRef("");
  const shipShownRef = useRef(false);
  queryRef.current = query;
  /* ★ OP3 §2: مرجع الحساب الحي — يُقرأ في alive()/الردود بدل closure
     قديمة (مقارنة closure بنفسها لا تكشف تبدل الحساب أبداً). */
  customerIdRef.current = customerId ? Number(customerId) : null;

  /* الحركة: احترام تقليل الحركة في النظام. */
  useEffect(function () {
    let mq = null;
    function apply() {
      try { setReducedMotion(!!(mq && mq.matches)); } catch (e) {}
    }
    try {
      mq = window.matchMedia("(prefers-reduced-motion: reduce)");
      apply();
      if (mq.addEventListener) mq.addEventListener("change", apply);
      else if (mq.addListener) mq.addListener(apply);
    } catch (e) {}
    return function () {
      try {
        if (mq && mq.removeEventListener) mq.removeEventListener("change", apply);
        else if (mq && mq.removeListener) mq.removeListener(apply);
      } catch (e) {}
    };
  }, []);

  /* تبدّل الحساب: إسقاط كل شيء — لا أحدث طلب لحساب سابق. */
  useEffect(function () {
    const cur = customerId ? Number(customerId) : null;
    if (accountRef.current === cur) return;
    accountRef.current = cur;
    try { if (abortRef.current) abortRef.current.abort(); } catch (e) {}
    try { if (timerRef.current) clearTimeout(timerRef.current); } catch (e) {}
    timerRef.current = 0;
    seqRef.current++;
    /* ★ OP4 §F1: إبطال دورة السجل القديمة هنا أيضاً — الرد المتأخر
       للحساب السابق لا يُكتب فوق الجديد حتى قبل بدء تحميله. */
    try { if (historyAbortRef.current) historyAbortRef.current.abort(); } catch (e) {}
    historyAbortRef.current = null;
    historyTokenRef.current = (Number(historyTokenRef.current) || 0) + 1;
    /* ★ OP3 §2: إسقاط المرجع المتزامن مع إبطال التسلسل — لا مقارنة قديمة. */
    queryRef.current = null;
    setQuery(null);
    setShip(null);
    shipShownRef.current = false;
    setLoadState("idle");
    setLoadError("");
    setPolling(false);
    setHistory([]);
    setHistoryState("idle");
    setShowPublicSearch(false);
    attemptsRef.current = 0;
    startedAtRef.current = 0;
  }, [customerId]);

  /* إلغاء عند المغادرة/unmount. */
  useEffect(function () {
    return function () {
      seqRef.current++;
      /* ★ OP4 §F1: إبطال دورة السجل عند unmount — لا كتابة بعد المغادرة. */
      historyTokenRef.current = (Number(historyTokenRef.current) || 0) + 1;
      try { if (historyAbortRef.current) historyAbortRef.current.abort(); } catch (e) {}
      historyAbortRef.current = null;
      try { if (abortRef.current) abortRef.current.abort(); } catch (e) {}
      try { if (timerRef.current) clearTimeout(timerRef.current); } catch (e) {}
    };
  }, []);

  const flash = useCallback(function (text) {
    if (text) dispatch(uiActions.toastShown(text));
  }, [dispatch]);

  function stopPolling() {
    try { if (timerRef.current) clearTimeout(timerRef.current); } catch (e) {}
    timerRef.current = 0;
    setPolling(false);
  }

  /* جلبة واحدة حسب الاستعلام — ترجع norm أو تقذف. */
  function fetchOnce(q, signal) {
    if (!q) return Promise.reject(new Error("no query"));
    if (q.kind === "public") return fetchPublicTracking(q.voucher, { signal: signal });
    if (q.kind === "latest") return fetchLatestShipment({ signal: signal });
    return fetchOrderShipmentOP1(Number(q.orderId), { signal: signal });
  }

  /* حلقة التتبع: جلبة → قرار متابعة → جدولة. seq + account + query
     تُفحص قبل كل كتابة حالة وكل جدولة — لا كتابة متأخرة أبداً. */
  const runLoop = useCallback(function (q, firstShip) {
    const mySeq = (seqRef.current = (Number(seqRef.current) || 0) + 1);
    const myAccount = customerId ? Number(customerId) : null;
    const qSig = JSON.stringify(q);
    try { if (abortRef.current) abortRef.current.abort(); } catch (e) {}
    try { if (timerRef.current) clearTimeout(timerRef.current); } catch (e) {}
    timerRef.current = 0;
    let aborter = null;
    try { aborter = new AbortController(); } catch (e) { aborter = null; }
    abortRef.current = aborter;
    attemptsRef.current = 0;
    startedAtRef.current = Date.now();
    /* ★ استعلام جديد = نتيجة جديدة: مرآة العرض تُصفَّر هنا (الناتج القديم
       لا يُحتسب نتيجة للاستعلام الحالي عند بوابة الميزانية). */
    shipShownRef.current = !!firstShip;
    lastRateMsgRef.current = "";
    if (firstShip) {
      if (seqRef.current !== mySeq) return;
      setShip(firstShip);
      shipShownRef.current = true;
      setLoadState("ready");
      setLoadError("");
    } else {
      setLoadState("loading");
      setLoadError("");
    }

    function alive() {
      if (seqRef.current !== mySeq) return false;
      /* ★ OP3 §2: مرجع الحساب الحي — مقارنة closure قديمة بنفسها
         لا تكشف تبدل الحساب أبداً. */
      const cur = customerIdRef.current;
      if ((cur || null) !== (myAccount || null)) return false;
      const qc = queryRef.current;
      if (JSON.stringify(qc) !== qSig) return false;
      return true;
    }
    function schedule(delayMs) {
      if (!alive()) return;
      try { if (timerRef.current) clearTimeout(timerRef.current); } catch (e) {}
      timerRef.current = setTimeout(tick, Math.max(0, delayMs));
    }
    function tick() {
      if (!alive()) return;
      if (typeof document !== "undefined" && document.hidden) {
        /* مخفية: أعد المحاولة لاحقاً بلا عدّ محاولة. */
        schedule(5000);
        return;
      }
      /* ★ الجولة الجديدة §F2: بوابة ما قبل الإرسال — الموعد النهائي
         (الجدار الزمني) والميزانية (العدّ) والهوية تُفحص داخل tick قبل
         fetchOnce، وكذلك عند الاستئناف بعد إخفاء الصفحة.
         ملاحظة العدّ: فحص attempt قبل الإرسال يختلف عن فحصه بعد زيادة
         العداد — لذلك يُفحص بالقيمة الحالية (cur) قبل الزيادة: الإرسال
         رقم cur+1 مسموح iff الفحص بقيمة cur سالك، وهو نفس ما كان يسمحه
         فحص ما بعد الرد سابقاً — فلا ينقص العدد المسموح بواحد.
         انتهاء الميزانية هنا = مخرج خطأ صريح + إعادة يدوية (كأي فشل)،
         لا جدولة صامتة ولا إرسال بعد انتهاء الميزانية. */
      if (!alive()) return;
      const curAttempts = (Number(attemptsRef.current) || 0);
      const preGate = shouldContinueOP1Poll({
        group: "Pending",
        contractMismatch: false,
        shouldPoll: true,
        attempts: curAttempts,
        startedAtMs: startedAtRef.current
      });
      if (!preGate.cont) {
        /* ★ انتهاء الميزانية هنا = مخرج خطأ صريح + إعادة يدوية (كأي فشل)
           — لكن بلا طمس نتيجة معروضة: إن كانت هناك شحنة ظاهرة نبقيها
           ونوقف المتابعة بصمت (كمسار النجاح سابقاً). */
        if (!shipShownRef.current) {
          setLoadState("error");
          setLoadError(lastRateMsgRef.current || "انتهت مدة المتابعة — أعد المحاولة يدوياً.");
        }
        stopPolling();
        return;
      }
      attemptsRef.current = curAttempts + 1;
      const signal = aborter ? aborter.signal : undefined;
      fetchOnce(q, signal).then(function (norm) {
        if (!alive()) return;
        /* ★ OP3 §2: فحص الحساب الحي — لا closure قديمة. */
        if ((customerIdRef.current || null) !== (myAccount || null)) return;
        norm.orderId = Number((q && q.orderId) || norm.orderId) || norm.orderId || 0;
        setShip(norm);
        shipShownRef.current = true;
        setLoadState("ready");
        setLoadError("");
        try {
          if (resultHeadRef.current && resultHeadRef.current.focus) resultHeadRef.current.focus({ preventScroll: true });
        } catch (e) {}
        const dec = shouldContinueOP1Poll({
          group: norm.group,
          contractMismatch: !!norm.contractMismatch,
          shouldPoll: norm.shouldPoll,
          attempts: attemptsRef.current,
          startedAtMs: startedAtRef.current
        });
        if (!dec.cont) {
          stopPolling();
          return;
        }
        setPolling(true);
        const waitMs = Math.max(15000, Math.min(60000, Number(norm.pollAfterSeconds) > 0 ? Math.round(Number(norm.pollAfterSeconds) * 1000) : 30000));
        schedule(waitMs);
      }, function (err) {
        if (!alive()) return;
        if (err && (err.name === "AbortError" || err.code === "EABORTED")) return;
        const c = classifyTrackingError(err, q.kind === "public");
        if (c.kind === "rate_limited") {
          /* ★ OP4 §F4: ميزانية المحاولات/المدة تُحترم هنا أيضاً (كمسار
             النجاح عبر shouldContinueOP1Poll) — لا حلقة 429 غير محدودة.
             Retry-After الخادم يُحترم كاملاً بلا تقصير لمدة أطول (لا طلب
             مبكر)؛ غياب قيمة موجبة = 30 ثانية. انتهاء الميزانية = مخرج
             خطأ صريح مع زر إعادة (كأي فشل)، لا جدولة صامتة. */
          try { lastRateMsgRef.current = String(c.message || ""); } catch (eLR) {}
          const budgetDec = shouldContinueOP1Poll({
            group: "Pending",
            contractMismatch: false,
            shouldPoll: true,
            attempts: attemptsRef.current,
            startedAtMs: startedAtRef.current
          });
          if (!budgetDec.cont) {
            setLoadState("error");
            setLoadError(c.message);
            stopPolling();
            return;
          }
          const retrySecs = Number(c.retryAfter);
          const waitMs = (Number.isFinite(retrySecs) && retrySecs > 0)
            ? Math.round(retrySecs * 1000)
            : 30000;
          /* ★ الجولة الجديدة §F2: إن كان Retry-After يتجاوز الوقت المتبقي
             من الميزانية فلا نختصر انتظار الخادم (لا تقليص للمدة) ولا نرسل
             بعد انتهاء الميزانية — نوقف الحلقة الآن بمخرج واضح وإعادة
             يدوية وفق العقد. الاستيقاظ عند الحد أو بعده كانت ستُسقطه
             بوابة ما قبل الإرسال، لكن بلا طلب زائد أصلاً هنا. */
          try {
            const wallMs = Number(SHIPMENT_POLL_MAX_DURATION_MS) > 0 ? Number(SHIPMENT_POLL_MAX_DURATION_MS) : 0;
            const elapsedMs = Date.now() - Number(startedAtRef.current || Date.now());
            if (wallMs > 0 && (elapsedMs + waitMs) >= wallMs) {
              setLoadState("error");
              setLoadError(c.message);
              stopPolling();
              return;
            }
          } catch (eWB) {}
          setPolling(true);
          schedule(waitMs);
          return;
        }
        /* ★ OP3 §2: أول جلبة في الحلقة = حالة عادية «بلا شحنة بعد»
           (مسجل جديد) — لا تُقرأ loadState الـclosure القديمة. */
        if (q.kind !== "public" && attemptsRef.current <= 1 && (c.kind === "not_found")) {
          /* مسجل بلا شحنة بعد: حالة عادية — اعرض فارغاً مهذباً بلا خطأ. */
          setShip(null);
          shipShownRef.current = false;
          setLoadState("ready");
          setLoadError("");
          stopPolling();
          return;
        }
        setLoadState("error");
        setLoadError(c.message);
        stopPolling();
      });
    }
    tick();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  /* ★ OP3 §2: مالك واحد لبدء الاستعلام — المرجع والهوية يُضبطان تزامنياً
     (queryRef.current = q) قبل setQuery/runLoop، فلا تقرأ الحلقة مرجعاً
     قديماً (صفر fetch). كل المسارات الأربعة تمر من هنا: بحث الزائر +
     latest عند الدخول + اختيار طلب من السجل + إعادة المحاولة. */
  function startQuery(q, firstShip) {
    queryRef.current = q;
    setQuery(q);
    runLoop(q, firstShip);
  }

  /* المسجل: أحدث طلب تلقائياً عند الدخول. */
  useEffect(function () {
    if (!customerId) return;
    if (queryRef.current) return;
    const q = { kind: "latest" };
    startQuery(q, null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  /* سجل الطلبات للمسجل (زر واحد — لا جلب تلقائي مكلف).
     ★ OP4 §F1: مالك دورة مستقل للسجل — generation/request token +
     مرجع الحساب الحي + إلغاء الطلب السابق (AbortController).
     لا حارس historyState من closure إطلاقاً: القديمة loading/ready كانت
     تمنع بدء سجل الحساب الجديد في نفس الالتزام (بعد تصفير أثر التبدل)،
     ومسح الشاشة وحده لا يكفي. الفحص المزدوج — التوكن الحي ثم الحساب
     الحي — في النجاح والفشل قبل أي كتابة. */
  function loadHistory() {
    if (!customerId) return;
    const myAccount = Number(customerId);
    const myToken = (historyTokenRef.current = (Number(historyTokenRef.current) || 0) + 1);
    try { if (historyAbortRef.current) historyAbortRef.current.abort(); } catch (e) {}
    let aborter = null;
    try { aborter = new AbortController(); } catch (e) { aborter = null; }
    historyAbortRef.current = aborter;
    setHistoryState("loading");
    const req = (aborter && aborter.signal)
      ? fetchServerOrders(myAccount, 1, 20, { signal: aborter.signal })
      : fetchServerOrders(myAccount, 1, 20);
    Promise.resolve(req).then(function (page) {
      if (historyTokenRef.current !== myToken) return;
      if ((customerIdRef.current || null) !== (myAccount || null)) return;
      const rows = ((page && page.items) || []).map(normalizeServerRow);
      setHistory(rows);
      setHistoryState("ready");
    }, function (err) {
      if (historyTokenRef.current !== myToken) return;
      if ((customerIdRef.current || null) !== (myAccount || null)) return;
      if (err && (err.name === "AbortError" || err.code === "EABORTED")) return;
      setHistoryState("error");
    });
  }
  useEffect(function () {
    if (!customerId) return;
    /* حمّل السجل تلقائياً أسفل التتبع — صفحة التتبع تحتاجه دائماً. */
    loadHistory();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  function submitPublicSearch(e) {
    if (e && e.preventDefault) e.preventDefault();
    const v = String(voucher || "").trim();
    if (!v) {
      flash(en ? "Enter the shipment number first" : "أدخل رقم الشحنة أولاً");
      return;
    }
    const q = { kind: "public", voucher: v };
    startQuery(q, null);
  }

  function selectOrder(row) {
    const oid = Number(row && row.serverId) || 0;
    if (!oid) return;
    const q = { kind: "order", orderId: oid, invoiceNo: String(row.invoiceNo || "") };
    startQuery(q, null);
  }

  const queryLabel = query
    ? query.kind === "public"
      ? (en ? "Public search" : "بحث عام") + " · " + query.voucher
      : query.kind === "latest"
        ? (en ? "Latest order" : "أحدث طلب")
        : (en ? "Order " : "الطلب ") + (query.invoiceNo || ("#" + query.orderId))
    : "";

  return (
    <section className="container view ck ct tk" id="trackingView">
      <div className="ct-top">
        <Link className="ct-crumb" to={PATHS.home}>
          {en ? "Home" : "الرئيسية"} / <b>{en ? "Track my shipment" : "تتبع شحنتي"}</b>
        </Link>
      </div>

      <header className="ct-head">
        <span className="eyebrow">{en ? "Tracking" : "التتبع"}</span>
        <h1>
          {en ? "Track " : "تتبع "}<span className="gold-text">{en ? "my shipment" : "شحنتي"}</span>
        </h1>
        <p className="ct-sub">
          {customerId
            ? (en
              ? "We fetch your latest order automatically — no number needed. You can also search by another number below."
              : "نجلب أحدث طلباتك تلقائياً — بلا حاجة لإدخال الرقم. ويمكنك أيضاً البحث برقم آخر أدناه.")
            : (en
              ? "Enter your shipment number (VoucherNo) to see its journey."
              : "أدخل رقم شحنتك (VoucherNo) لرؤية رحلتها.")}
        </p>
      </header>

      {/* بحث الزائر / البحث العام */}
      {!customerId || showPublicSearch ? (
        <form className="ct-card tk-search" onSubmit={submitPublicSearch}>
          <label className="tk-search-label" htmlFor="tkVoucher">
            {en ? "Shipment number" : "رقم الشحنة"}
          </label>
          <input
            id="tkVoucher"
            className="ct-input tk-voucher"
            type="text"
            inputMode="text"
            autoComplete="off"
            dir="ltr"
            value={voucher}
            onChange={function (e) { setVoucher(e.target.value); }}
            placeholder="VoucherNo"
            aria-describedby="tkVoucherHint"
          />
          <p className="ck-hint" id="tkVoucherHint">
            {en ? "The number only — no account or personal data is shown here." : "الرقم فقط — لا يظهر هنا أي حساب أو بيانات شخصية."}
          </p>
          <button className="btn-primary tk-go" type="submit" disabled={loadState === "loading" && query && query.kind === "public"}>
            <span>{en ? "Track" : "تتبع"}</span>
            <Icon name="truck" strokeWidth={1.9} />
          </button>
        </form>
      ) : null}

      {customerId && !showPublicSearch ? (
        <p className="tk-alt-search">
          <button className="ck-edit" type="button" onClick={function () { setShowPublicSearch(true); }}>
            {en ? "Search by another number" : "البحث برقم آخر"}
          </button>
        </p>
      ) : null}

      {/* النتيجة */}
      {query ? (
        <div className="ct-card tk-card">
          <h3 className="ck-card-title" tabIndex={-1} ref={resultHeadRef}>
            <Icon name="truck" strokeWidth={1.8} />
            <span>{queryLabel}</span>
          </h3>
          {loadState === "loading" && !ship ? (
            <TrackSkeleton />
          ) : null}
          {loadState === "error" && !ship ? (
            <p className="ck-auth-warn" role="alert">
              {loadError}
              <button
                className="ck-edit"
                type="button"
                onClick={function () { if (query) startQuery(query, null); }}
              >
                {en ? "Retry" : "إعادة المحاولة"}
              </button>
            </p>
          ) : null}
          {!ship && loadState === "ready" && query.kind !== "public" ? (
            <p className="ck-hint">
              {en ? "No shipment for this order yet — this is normal at this stage." : "لا توجد شحنة لهذا الطلب بعد — وهذا طبيعي في هذه المرحلة."}
            </p>
          ) : null}
          {ship ? (
            <TrackResult ship={ship} language={language} polling={polling} reducedMotion={reducedMotion} />
          ) : null}
        </div>
      ) : null}

      {/* سجل المسجل */}
      {customerId ? (
        <div className="ct-card tk-history">
          <h3 className="ck-card-title">
            <Icon name="doc" strokeWidth={1.8} />
            <span>{en ? "My orders" : "سجل طلباتي"}</span>
          </h3>
          {historyState === "loading" ? (
            <ListRowsSkeleton count={3} label={en ? "Loading orders…" : "جارٍ تحميل الطلبات…"} />
          ) : historyState === "error" ? (
            <p className="ck-hint">
              {en ? "Could not load orders." : "تعذّر تحميل الطلبات."}{" "}
              <button className="ck-edit" type="button" onClick={function () { loadHistory(); }}>
                {en ? "Retry" : "إعادة المحاولة"}
              </button>
            </p>
          ) : history.length ? (
            <ul className="tk-orders">
              {history.map(function (row) {
                const active = query && query.kind === "order" && Number(query.orderId) === Number(row.serverId);
                return (
                  <li key={String(row.invoiceNo)}>
                    <button
                      type="button"
                      className={"tk-order" + (active ? " is-on" : "")}
                      aria-current={active ? "true" : undefined}
                      onClick={function () { selectOrder(row); }}
                    >
                      <span className="tk-order-no">#{row.invoiceNo}</span>
                      <span className="tk-order-meta">
                        {row.itemsCount} {en ? "items" : "قطعة"} · <Money sar={row.totals.total} />
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          ) : (
            <div className="tk-empty">
              <p><b>{en ? "No orders yet" : "لا توجد طلبات بعد"}</b></p>
              <p className="ck-hint">{en ? "Your confirmed orders will appear here." : "طلباتك المؤكدة ستظهر هنا."}</p>
              <Link className="btn-primary" to={PATHS.perfumes}>
                {en ? "Browse perfumes" : "تصفّح العطور"}
              </Link>
            </div>
          )}
          <p className="ck-hint">
            {en ? "Your history stays in your account — " : "سجلّك يبقى في حسابك — "}
            <Link to={PATHS.profile}>{en ? "My account" : "حسابي"}</Link>
          </p>
          {SHIPPING_SIMULATION ? <p className="ck-hint">({SHIPPING_SIMULATION_NOTE})</p> : null}
        </div>
      ) : null}
    </section>
  );
}
